import { Table, BooleanColumn, GenericColumn, TableNameColumn, StringColumn } from '../../db'

export const sc_cat_item_producer = Table({
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    extends: 'sc_cat_item',
    extensible: true,
    label: 'Record Producer',
    name: 'sc_cat_item_producer',
    schema: {
        can_cancel: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Controls whether a cancel button is shown on the record producer form',
                    label: 'Can cancel',
                    plural: 'Can cancels',
                },
            ],
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        table_name: TableNameColumn({
            attributes: {
                base_start: true,
                no_text_index: true,
                no_views: true,
            },
            label: 'Table name',
            mandatory: true,
        }),
        save_script: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'script_plain',
            default: `/**\r
* This script is executed at every step save in Catalog Builder. \r
* This script is executed before \`Script\` is executed.\r
* \`current\` Is the GlideRecord produced by Record Producer. \r
* To access the variables, use \`producer.var1\` where var1 is the name of the variable\r
* To access the Record Producer use \`cat_item\`\r
*/`,
            label: 'Save script',
            maxLength: 8000,
        }),
        save_options: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                no_text_index: true,
            },
            choices: {
                destination: {
                    label: 'Save in destination',
                    sequence: 10,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Save options',
        }),
        post_insert_script: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'script_plain',
            default: `/**\r
* This script is executed after the record is generated. \r
* \`current\` Is the GlideRecord produced by Record Producer. Use \`current.update()\` to update the record\r
* To access the variables, use \`producer.var1\` where var1 is the name of the variable\r
* To access the Record Producer use \`cat_item\`\r
*/`,
            label: 'Post insert script',
            maxLength: 8000,
        }),
        allow_edit: BooleanColumn({
            default: false,
            label: 'Allow edit',
        }),
        script: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'script_plain',
            default: `/** This script is executed before the Record is generated\r
* \`current\`- GlideRecord produced by Record Producer\r
* Don't use \`current.update()\` or \`current.insert()\` as the record is generated by Record Producer\r
* Don't use \`current.setValue('sys_class_name', 'xxx')\` as this will trigger reparent flow and can cause data loss\r
* Avoid \`current.setAbortAction()\` and generate a separate record\r
* Use \`producer.var1\` to access variables\r
*/`,
            label: 'Script',
            maxLength: 8000,
        }),
        redirect_url: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                no_text_index: true,
            },
            default: "javascript: gs.getProperty('glide.sc.producer.redirect_url', 'generated_record')",
            choices: {
                generated_record: {
                    label: 'Generated task record',
                    sequence: 10,
                },
                catalog_home: {
                    label: 'Catalog homepage',
                    sequence: 20,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Decides where to land after record creation. Works for Service Portal as well',
                    label: 'Redirect to',
                    plural: 'Redirect to',
                },
            ],
        }),
        view: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                no_text_index: true,
            },
            label: 'View',
        }),
    },
    textIndex: true,
})
